function () {
  if (!Auth.isLoggedIn()) {
    console.error('Unauthorzied');
    return;
  }
  const payload = Auth.decodeJWT(appsmith.store.jwt);
  const expiresIn = payload.exp * 1000 - Date.now();
  if (expiresIn <= 0) {
    Auth.logout();
    return;
  }
  if (appsmith.store.logoutTimer) {
    clearTimeout(appsmith.store.logoutTimer);
  }
  let logoutTimer = setTimeout(() => {
    Auth.logout();
  }, expiresIn);
  storeValue('logoutTimer', logoutTimer, true);
}

