		if (!this.isLoggedIn()){
			console.error('Unauthorzied');
			return;
		}

		const token = appsmith.store.jwt;
		const payload = token.split(".")[1];

		try {
			return JSON.parse(
				atob(payload.replace(/-/g, "+").replace(/_/g, "/"))
